const matCache=new Map();
function mat(color,opts={}){if(Object.keys(opts).length)return new THREE.MeshStandardMaterial({color,roughness:.86,...opts});if(!matCache.has(color))matCache.set(color,new THREE.MeshStandardMaterial({color,roughness:.86}));return matCache.get(color);}
function mesh(geo,color,parent=scene,opts={}){const m=new THREE.Mesh(geo,mat(color,opts));m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function ball(parent,x,y,z,r,color,scale=[1,1,1]){const m=mesh(new THREE.SphereGeometry(r,12,8),color,parent);m.position.set(x,y,z);m.scale.set(...scale);return m;}
function link(parent,a,b,r,color,r2=r){const v1=new THREE.Vector3(...a),v2=new THREE.Vector3(...b);const m=mesh(new THREE.CylinderGeometry(r2,r,v1.distanceTo(v2),7),color,parent);m.position.copy(v1).add(v2).multiplyScalar(.5);m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),v2.sub(v1).normalize());return m;}
function ground(x,z){const d=Math.sqrt((x/25)**2+(z/18)**2);return d<.8?.39:Math.max(-.3,.39-(d-.8)*2.0);}
function ellipse(x,z){return Math.sqrt((x/25)**2+(z/18)**2);}
function addObject(type,x,z,group,extra={}){group.position.set(x,ground(x,z),z);scene.add(group);const obj={type,x,z,group,...extra};worldObjects.push(obj);return obj;}
function textSprite(text,color='#527d66',scale=1){const c=document.createElement('canvas');c.width=512;c.height=96;const ctx=c.getContext('2d');ctx.font='500 30px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='rgba(255,251,229,.90)';ctx.beginPath();ctx.roundRect(14,15,484,66,30);ctx.fill();ctx.fillStyle=color;ctx.fillText(text,256,50);const sp=new THREE.Sprite(new THREE.SpriteMaterial({map:new THREE.CanvasTexture(c),transparent:true,depthWrite:false}));sp.scale.set(4.8*scale,.9*scale,1);return sp;}

// The beach is a real mesh, with a submerged shelf around the whole island.
function island(){const N=110,R=16,verts=[],cols=[],idx=[];const c0=new THREE.Color('#eedcac'),c1=new THREE.Color('#f5e8bd'),c2=new THREE.Color('#b9d5b8');verts.push(0,.39,0);cols.push(c1.r,c1.g,c1.b);for(let r=1;r<=R;r++)for(let i=0;i<=N;i++){const a=i/N*Math.PI*2,f=r/R*1.15,edge=1+.035*Math.sin(a*5)+.025*Math.cos(a*9);const x=Math.cos(a)*25*f*edge,z=Math.sin(a)*18*f*edge,y=ground(x,z)+(r<R?Math.sin(x*.34)*Math.sin(z*.44)*.025:0);verts.push(x,y,z);const cc=(f>.86?c2.clone().lerp(c0,clamp((1.08-f)*4,0,1)):c1.clone().lerp(c0,.18+rand()*.27));cols.push(cc.r,cc.g,cc.b);}
for(let i=0;i<N;i++)idx.push(0,1+i+1,1+i);for(let r=1;r<R;r++)for(let i=0;i<N;i++){const a=1+(r-1)*(N+1)+i,b=a+N+1;idx.push(a,b+1,b,a,a+1,b+1);}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));g.setAttribute('color',new THREE.Float32BufferAttribute(cols,3));g.setIndex(idx);g.computeVertexNormals();const m=new THREE.Mesh(g,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));m.receiveShadow=true;scene.add(m);
const lower=mesh(new THREE.CylinderGeometry(25,22,1.2,80),0xb8c3a4);lower.scale.z=.73;lower.position.y=-1.0;}
island();
const waterUniforms={uTime:{value:0},uColor:{value:new THREE.Color('#62bec4')}};
const water=new THREE.Mesh(new THREE.PlaneGeometry(240,240,1,1),new THREE.ShaderMaterial({transparent:true,uniforms:waterUniforms,vertexShader:'varying vec3 wp; void main(){ wp=(modelMatrix*vec4(position,1.0)).xyz;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}',fragmentShader:'varying vec3 wp; uniform float uTime; uniform vec3 uColor; void main(){ float a=sin(wp.x*1.6+sin(wp.z*1.8+uTime*.4)+uTime*.3);float b=sin(wp.z*2.5+sin(wp.x*.8-uTime*.3));float ca=pow(max(0.,a*b),8.);float wave=sin(wp.z*.3+wp.x*.15-uTime*.5)*.025; vec3 col=uColor+vec3(ca*.14+wave);gl_FragColor=vec4(col,.84); }'}));water.rotation.x=-Math.PI/2;water.position.y=-.15;water.renderOrder=1;scene.add(water);
const foamRings=[];
for(let k=0;k<3;k++){const points=[];for(let i=0;i<=130;i++){const a=i/130*Math.PI*2,edge=1+.035*Math.sin(a*5)+.025*Math.cos(a*9);points.push(new THREE.Vector3(Math.cos(a)*(25.0+k*.36)*edge,-.09,Math.sin(a)*(18+k*.26)*edge));}const geo=new THREE.BufferGeometry().setFromPoints(points);const line=new THREE.Line(geo,new THREE.LineBasicMaterial({color:0xeef5cf,transparent:true,opacity:.35-k*.08}));scene.add(line);foamRings.push(line);}

function shellModel(id,scale=1){const g=new THREE.Group(),s=SHELLS[id];if(id===1){const core=ball(g,0,.12,0,.87,s.color,[1,.53,.9]);for(let i=0;i<10;i++){const a=(i/9)*Math.PI;const points=[];for(let j=0;j<14;j++){const t=j/13;points.push(new THREE.Vector3(Math.cos(a)*t*.85,.15+Math.sin(t*Math.PI)*.4,Math.sin(a)*t*1.18-.5));}const r=mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points),14,.033,4,false),s.accent,g);r.castShadow=false;}ball(g,0,.1,-.5,.25,s.accent,[1.2,.5,.8]);core.rotation.x=.15;}
else {ball(g,0,.2,0,.81,s.color,[1,.9,.92]);const pts=[];for(let i=0;i<100;i++){const t=i/99,a=t*Math.PI*4.6,r=.72*(1-t)+.065;pts.push(new THREE.Vector3(Math.cos(a)*r,.36+Math.sin(a)*r,-.57-.32*t));}mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts),100,.065,6,false),s.accent,g);const backPts=pts.map(p=>new THREE.Vector3(p.x,p.y,-p.z));mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(backPts),100,.045,5,false),s.accent,g);const opening=ball(g,.25,-.16,.5,.35,0x7b674e,[1,.73,.6]);opening.rotation.z=-.2;
if(id===2||id===4){for(let j=0;j<4;j++){const con=mesh(new THREE.ConeGeometry(.57-j*.11,.62,12),j%2?s.accent:s.color,g);con.rotation.x=-Math.PI/2;con.position.set(0,.25,-.62-j*.25);}}
if(id===3||id===4){for(let j=0;j<8;j++){const a=j/8*Math.PI*2;const spike=mesh(new THREE.ConeGeometry(.16,id===3?.48:.31,5),s.accent,g);spike.position.set(Math.cos(a)*.69,.2+Math.sin(a)*.66,-.05);spike.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),new THREE.Vector3(Math.cos(a),Math.sin(a),-.1).normalize());}}}
g.scale.setScalar(scale);return g;}
function crabModel(shellId=0,color=0xdb7154,size=1){const g=new THREE.Group(),body=new THREE.Group();g.add(body);ball(body,0,.55,.2,.49,color,[1.12,.58,1]);const legs=[];for(let side of [-1,1]){for(let i=0;i<3;i++){const l=new THREE.Group();l.position.set(side*.31,.47,.25+(i-1)*.3);const knee=[side*(.5+(i===1?.1:0)),-.04,.08*(i-1)];link(l,[0,0,0],knee,.059,color,.044);link(l,knee,[side*.64,-.38,.22*(i-1)],.045,0xc66549,.019);body.add(l);legs.push(l);}const arm=new THREE.Group();arm.position.set(side*.35,.59,.44);link(arm,[0,0,0],[side*.37,-.01,.4],.1,color,.07);ball(arm,side*.41,0,.49,side===-1?.24:.18,color,[1,.7,1.22]);const claw1=ball(arm,side*.46,.035,.69,.11,0xef9a6b,[.8,.6,1.3]);claw1.rotation.y=side*.5;ball(arm,side*.32,.04,.65,.09,0xef9a6b,[.6,.7,1.2]);body.add(arm);}
for(let side of [-1,1]){link(body,[side*.2,.65,.43],[side*.24,1.03,.6],.045,color);ball(body,side*.24,1.03,.6,.106,0x423b32);ball(body,side*.264,1.066,.67,.032,0xfff8dc);}
const shell=shellModel(shellId);shell.position.set(0,1.06,-.3);shell.rotation.set(.18,Math.PI,0);body.add(shell);g.scale.setScalar(size);return{group:g,body,legs,shell};}
