function replacePlayerShell(){player.body.remove(player.shell);player.shell=shellModel(state.shell);player.shell.position.set(0,1.06,-.3);player.shell.rotation.set(.18,Math.PI,0);player.body.add(player.shell);}

function rock(x,z,size=1,color=0x8eaa9c){const g=new THREE.Group();for(let i=0;i<3;i++){const r=mesh(new THREE.DodecahedronGeometry(size*(i===0?1:.6),0),color,g);r.position.set(i===0?0:between(-size,size),size*.3,i===0?0:between(-size*.5,size*.5));r.scale.set(1,.7+rand()*.4,.9);r.rotation.set(rand(),rand()*4,rand());}g.position.set(x,ground(x,z),z);scene.add(g);return g;}
function palm(x,z,height=4){const g=new THREE.Group();for(let i=0;i<7;i++){link(g,[Math.sin(i*.18)*.8,i*height/7,0],[Math.sin((i+1)*.18)*.8,(i+1)*height/7,0],.19-i*.009,i%2?0xb29a65:0xa08c59,.175-i*.009);}const tip=new THREE.Vector3(Math.sin(1.26)*.8,height,0);for(let j=0;j<7;j++){const a=j/7*Math.PI*2+rand()*.3;const len=between(2.4,3.2);const vs=[],indices=[];for(let k=0;k<=9;k++){const t=k/9,dist=t*len,y=Math.sin(t*Math.PI)*.64-t*t*.6,width=Math.sin(t*Math.PI)*.47;vs.push(Math.cos(a)*dist+Math.cos(a+Math.PI/2)*width,y,Math.sin(a)*dist+Math.sin(a+Math.PI/2)*width,Math.cos(a)*dist-Math.cos(a+Math.PI/2)*width,y-.07,Math.sin(a)*dist-Math.sin(a+Math.PI/2)*width);if(k<9){const n=k*2;indices.push(n,n+1,n+2,n+1,n+3,n+2);}}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(vs,3));geo.setIndex(indices);geo.computeVertexNormals();const leaf=mesh(geo,j%2?0x6b9b68:0x80ae71,g,{side:THREE.DoubleSide});leaf.position.copy(tip);palms.push(leaf);}for(let i=0;i<3;i++)ball(g,tip.x+between(-.3,.3),height-.16,between(-.3,.3),.22,0x81804b);g.position.set(x,ground(x,z),z);g.rotation.y=rand()*6;scene.add(g);return g;}
