function star(x,z,size=.5,color=0xd89576){const sh=new THREE.Shape();for(let i=0;i<10;i++){const a=i/10*Math.PI*2,r=i%2?size*.38:size;const xx=Math.cos(a)*r,yy=Math.sin(a)*r;i?sh.lineTo(xx,yy):sh.moveTo(xx,yy);}sh.closePath();const m=mesh(new THREE.ExtrudeGeometry(sh,{depth:.10,bevelEnabled:true,bevelSize:.035,bevelThickness:.025,bevelSegments:1,steps:1}),color);m.rotation.x=-Math.PI/2;m.rotation.z=rand()*6;m.position.set(x,ground(x,z)+.04,z);return m;}
