const camp=new THREE.Group();const bed=mesh(new THREE.CylinderGeometry(1.5,1.6,.14,35),0xdfc68d,camp);bed.position.y=.02;for(let i=0;i<10;i++){const a=i/10*Math.PI*2;ball(camp,Math.cos(a)*1.55,.08,Math.sin(a)*1.55,.22,0xbabca0,[1.3,.6,1]);}const home=shellModel(2,1.75);home.position.set(-.1,.65,-.1);home.rotation.y=1.2;camp.add(home);const flagPole=link(camp,[1.9,0,-.5],[1.9,2.5,-.5],.045,0x977f53);const flag=mesh(new THREE.PlaneGeometry(.8,.5),0xe5a071,camp,{side:THREE.DoubleSide});flag.position.set(2.3,2.19,-.5);const campLabel=textSprite('⌂  贝壳小屋');campLabel.position.set(0,3.7,0);camp.add(campLabel);const campObj=addObject('camp',-7,9,camp);
