// Small shell portraits are rendered from the same 3D models used in the game.
const portraits=[];
{const pScene=new THREE.Scene();pScene.add(new THREE.HemisphereLight(0xfff2d3,0x779786,3));const light=new THREE.DirectionalLight(0xffeed0,4);light.position.set(-3,5,4);pScene.add(light);const pCam=new THREE.PerspectiveCamera(34,1,.1,20);pCam.position.set(2.5,2.1,-4.8);pCam.lookAt(0,.2,0);const pr=new THREE.WebGLRenderer({alpha:true,antialias:true});pr.setSize(220,220);pr.outputColorSpace=THREE.SRGBColorSpace;pr.toneMapping=THREE.ACESFilmicToneMapping;for(let i=0;i<5;i++){const s=shellModel(i);pScene.add(s);pr.render(pScene,pCam);portraits.push(pr.domElement.toDataURL('image/png'));pScene.remove(s);}pr.dispose();}

function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3300);}
function save(){if(resetting)return;state.shellLayout=shellObjects.map(o=>o.id);state.x=player.group.position.x;state.z=player.group.position.z;state.sound=soundEnabled;try{localStorage.setItem(SAVE_KEY,JSON.stringify({...state,version:1}));}catch{} }
function sound(type='pickup'){if(!soundEnabled)return;try{if(!audio)audio=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const notes=type==='swap'?[392,494,587,784]:type==='hurt'?[180,130]:type==='win'?[392,494,587,784,988]:type==='food'?[660,880]:[660,880,1108];notes.forEach((f,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.type=type==='hurt'?'triangle':'sine';o.frequency.value=f;g.gain.setValueAtTime(0,audio.currentTime+i*.09);g.gain.linearRampToValueAtTime(.07,audio.currentTime+i*.09+.015);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+i*.09+.28);o.start(audio.currentTime+i*.09);o.stop(audio.currentTime+i*.09+.3);});}catch{} }
function sparkle(position,color=0xf7d98a,count=14){for(let i=0;i<count;i++){const m=new THREE.Mesh(new THREE.OctahedronGeometry(.065+rand()*.06),mat(color,{emissive:color,emissiveIntensity:.2}));m.position.copy(position).add(new THREE.Vector3(0,.8,0));scene.add(m);particles.push({mesh:m,velocity:new THREE.Vector3(between(-1.7,1.7),between(1.5,3.4),between(-1.7,1.7)),life:1});}}
function openModal(html){modalReturn=document.activeElement;keys.clear();input.x=input.z=0;moveTarget=null;dialogOpen=true;$('modal').innerHTML=`<button class="close-button" id="close-modal" aria-label="关闭">×</button>${html}`;$('modal-backdrop').classList.remove('hidden');$('close-modal').onclick=closeModal;$('modal').focus();}
function closeModal(){dialogOpen=false;$('modal-backdrop').classList.add('hidden');if(paused){paused=false;$('pause-button').textContent='Ⅱ';$('pause-button').setAttribute('aria-label','暂停');}modalReturn?.focus?.();keys.clear();}
const statLines=s=>`<div class="stat-line"><span>移动速度</span><b>${Math.round(s.speed*100)}%</b></div><div class="stat-line"><span>伤害减免</span><b>${Math.round(s.armor*100)}%</b></div><div class="stat-line"><span>抗浪等级</span><b>${'●'.repeat(s.tide)}${'○'.repeat(3-s.tide)}</b></div>`;
function inspectShell(obj){const s=SHELLS[obj.id],current=SHELLS[state.shell];if(!state.discovered.includes(obj.id)){state.discovered.push(obj.id);save();updateHUD();}openModal(`<p class="modal-eyebrow">FOUND A LITTLE POSSIBILITY · ${s.rarity}</p><h2 id="modal-title">${s.name}</h2><img class="shell-preview" src="${portraits[obj.id]}" alt="${s.name} 3D 模型"><p class="subtext">${s.desc}</p><div class="comparison"><div class="compare-column"><span>现在的家</span><h3>${current.name}</h3>${statLines(current)}</div><div class="compare-column new"><span>发现的新家</span><h3>${s.name}</h3>${statLines(s)}</div></div><p class="subtext">${s.ability}<br>换壳后，旧家会留在这里，随时可以回来。</p><div class="button-row"><button class="secondary-button" id="keep-shell">再想想</button><button class="primary-button" id="swap-shell" ${obj.id===state.shell?'disabled':''}>${obj.id===state.shell?'已经住在相同的壳里':'搬进这个新家'} <span>✦</span></button></div>`);$('keep-shell').onclick=closeModal;$('swap-shell').onclick=()=>{const old=state.shell;state.shell=obj.id;state.swaps++;obj.id=old;obj.group.remove(obj.model);obj.model=shellModel(old,1.16);obj.model.position.y=.48;obj.group.add(obj.model);obj.halo.material.color.set(SHELLS[old].accent);replacePlayerShell();closeModal();sound('swap');sparkle(player.group.position,SHELLS[state.shell].accent,22);toast(`搬家成功！${SHELLS[state.shell].ability}`);updateHUD();save();};}
function showJournal(){openModal(`<p class="modal-eyebrow">YOUR SHELL COLLECTION</p><h2 id="modal-title">每一个家，都有故事。</h2><p class="subtext">已发现 ${state.discovered.length} / 5 种贝壳。沿着海岸走走，总有新的相遇。</p><div class="journal-grid">${SHELLS.map((s,i)=>`<div class="journal-item ${state.discovered.includes(i)?'':'locked'}"><img src="${portraits[i]}" alt="${state.discovered.includes(i)?s.name:'未知贝壳'}"><h3>${state.discovered.includes(i)?s.name:'尚未发现'}</h3><p>${state.discovered.includes(i)?s.rarity:'探索海岛来解锁'}</p></div>`).join('')}</div><div class="stat-summary"><div><b>${state.swaps}</b>次搬家</div><div><b>${state.food}</b>份美食</div><div><b>${Math.floor(state.distance)}</b>米足迹</div></div><button class="primary-button" id="journal-close">继续写下你的故事 <span>✦</span></button><p class="save-note">进度自动保存在此浏览器</p>`);$('journal-close').onclick=closeModal;}
function showHelp(){openModal(`<p class="modal-eyebrow">A SMALL FIELD GUIDE</p><h2 id="modal-title">海岸生活指南</h2><div class="help-grid"><div><kbd>WASD / ↑↓←→</kbd>移动</div><div><kbd>E</kbd>靠近后互动</div><div><kbd>空格</kbd>按住冲刺</div><div><kbd>Shift</kbd>按住躲藏</div><div><kbd>J</kbd>贝壳图鉴</div><div><kbd>Esc</kbd>暂停 / 关闭</div></div><ul class="tips"><li>也可以点击沙滩移动，触屏设备用左下角摇杆。</li><li>靠近贝壳，比较速度、防御和抗浪能力。旧壳会留在原地。</li><li>找到地图上 3 颗金色珍珠，再返回贝壳小屋。</li><li>捡拾金黄的果实恢复活力；小屋旁也能慢慢恢复。</li><li>海鸥出现红圈时躲进壳里！沙蟹会在宝藏附近巡逻。</li><li>涨潮会减缓浅滩移动；厚壳抗浪，低潮更适合探索。</li><li>体力用完仍然可以行走。被打败会回到小屋，保留探索成果。</li></ul><button class="primary-button" id="help-close">记住啦，出发 <span>✦</span></button>`);$('help-close').onclick=closeModal;}
function showPause(){if(!started){showHelp();return;}if(dialogOpen){closeModal();return;}paused=true;$('pause-button').textContent='▷';$('pause-button').setAttribute('aria-label','继续游戏');save();openModal(`<p class="modal-eyebrow">TAKE A LITTLE BREATH</p><h2 id="modal-title">让海风等你一会儿。</h2><p class="subtext">你的冒险已经保存在这个浏览器里。<br>小岛会在这里，等你回来。</p><div class="stat-summary"><div><b>${Math.floor(state.elapsed/60)}:${String(Math.floor(state.elapsed%60)).padStart(2,'0')}</b>探索时间</div><div><b>${state.pearls.length} / 3</b>潮汐珍珠</div><div><b>${state.discovered.length} / 5</b>发现的家</div></div><button class="primary-button" id="resume-button">继续这场冒险 <span>✦</span></button><button class="reset-button" id="reset-button">重新开始一场冒险</button>`);$('resume-button').onclick=closeModal;$('reset-button').onclick=()=>{openModal(`<p class="modal-eyebrow">A FRESH START</p><h2 id="modal-title">重新写一本寄居日记？</h2><p class="subtext">当前的探索进度、珍珠和贝壳图鉴将清空。</p><div class="button-row"><button class="secondary-button" id="cancel-reset">保留冒险</button><button class="primary-button" id="confirm-reset">重新出发 <span>✦</span></button></div>`);$('cancel-reset').onclick=closeModal;$('confirm-reset').onclick=()=>{resetting=true;try{localStorage.removeItem(SAVE_KEY);}catch{}location.reload();};};}
function interact(){if(!started||dialogOpen||paused)return;if(!nearest){toast('再靠近一点，贝壳和小伙伴就在附近。');return;}if(nearest.type==='shell')inspectShell(nearest);if(nearest.type==='npc'){openModal(`<p class="modal-eyebrow">阿壳 · 一位老朋友</p><h2 id="modal-title">「别急，总有适合你的家。」</h2><div class="npc-quote">${state.pearls.length===3?'你居然找齐了三颗珍珠！带回小屋吧，今天晚上，我们要把它们挂成最亮的灯。':state.swaps===0?'海浪在前面的沙滩留下了一枚桃桃扇贝。去试一试吧。家不一定要最大，要刚刚好。':'看见地图上的金色光点了吗？森林边、岩石湾和珊瑚浅滩各藏着一颗珍珠。涨潮的时候，厚一点的壳会帮上忙。'}</div><p class="subtext">小提示：${state.swaps===0?'靠近前方的桃色贝壳，按 E 就能查看。':'海鸥不喜欢硬邦邦的东西。被盯上时，按住 Shift 躲起来就好。'}</p><button class="primary-button" id="npc-close">谢谢你，阿壳 <span>✦</span></button>`);$('npc-close').onclick=closeModal;}if(nearest.type==='camp'){state.health=100;state.stamina=100;sound('food');sparkle(player.group.position,0xb8d8a4);if(state.pearls.length===3&&state.swaps>0&&!state.won)win();else toast(state.won?'欢迎回家。新的风景还在等你。':'在小屋歇了歇，活力和体力全部恢复。');save();updateHUD();}}
function win(){state.won=true;save();sound('win');sparkle(player.group.position,0xffdc7c,45);openModal(`<div class="ending-symbol">✦</div><p class="modal-eyebrow">EVERY JOURNEY LEADS HOME</p><h2 id="modal-title">世界很大，<br>你也找到了自己的光。</h2><p class="subtext">三颗潮汐珍珠点亮了贝壳小屋。<br>这趟旅途中，你把每一个陌生的地方，走成了熟悉的风景。</p><div class="stat-summary"><div><b>${Math.floor(state.elapsed/60)}分${Math.floor(state.elapsed%60)}秒</b>这次旅途</div><div><b>${state.swaps}</b>次勇敢搬家</div><div><b>${state.discovered.length}/5</b>不同的家</div></div><button class="primary-button" id="continue-explore">小岛还有故事，继续探索 <span>✦</span></button><p class="save-note">冒险完成 · 可以继续收集全部 5 种贝壳</p>`);$('continue-explore').onclick=()=>{closeModal();updateHUD();};}
function hurt(amount){if(invuln>0||hide||!started)return;state.health=Math.max(0,state.health-amount*(1-SHELLS[state.shell].armor));invuln=2.2;sound('hurt');sparkle(player.group.position,0xe99676,8);if(state.health<=0){player.group.position.set(-4,.39,8);state.health=100;state.stamina=100;moveTarget=null;bird.phase='cruise';bird.timer=25;birdTarget.visible=false;toast('阿壳把你送回了小屋。珍珠和探索成果都还在！');invuln=5;save();}else toast('受伤了！吃点果实，或回小屋歇一会儿。');}
const questTitles=['家，要刚刚好','追寻海浪的礼物','把星光装进口袋','带着星光，回家'];
const questDescriptions=['找到沙滩上的贝壳，试着换一个新家。','前往地图上的金色光点，找到第一颗潮汐珍珠。','探索岩石湾、椰影林地和珊瑚浅滩，找齐 3 颗珍珠。','把 3 颗珍珠带回贝壳小屋，点亮属于你的小小世界。'];
function questStage(){return !state.swaps?0:state.pearls.length===0?1:state.pearls.length<3?2:3;}
function updateHUD(){const s=SHELLS[state.shell],q=questStage();$('equipped-name').textContent=s.name;$('shell-rarity').textContent=s.rarity;$('equipped-art').innerHTML=`<img src="${portraits[state.shell]}" alt="${s.name}">`;$('speed-stat').textContent='●'.repeat(s.speed>1.1?3:s.speed>=.9?2:1)+'○'.repeat(s.speed>1.1?0:s.speed>=.9?1:2);$('defense-stat').textContent='●'.repeat(s.armor>.4?3:s.armor>.15?2:1)+'○'.repeat(s.armor>.4?0:s.armor>.15?1:2);$('quest-title').textContent=state.won?'海岸，还有新故事':questTitles[q];$('quest-desc').textContent=state.won?`冒险已完成。继续寻找不同的家，图鉴已收集 ${state.discovered.length} / 5。`:questDescriptions[q];$('quest-count').textContent=state.won?'完成':`0${q+1} / 04`;$('quest-progress').style.width=(state.won?100:q*25+5)+'%';$('quest-detail').textContent=state.won?'自由探索中':q===0?'靠近贝壳，按 E 查看':q===3?'回到小屋，按 E 互动':'金色光点标记了珍珠';$('pearls-count').textContent=state.pearls.length;$('discovered-count').textContent=`${state.discovered.length} / 5 种家`;}
let lastRegion='';
function regionAt(x,z){if(x>12)return['coral','03 — CORAL TIDEPOOLS','珊瑚浅滩'];if(z<-5&&x>-10)return['grove','02 — THE PALM GROVE','椰影林地'];if(x<-11)return['rocks','04 — ROCKY COVE','岩石湾'];return['shore','01 — THE SHORE','暖沙海岸'];}
function tickHUD(){ $('health-meter').style.width=state.health+'%';$('stamina-meter').style.width=state.stamina+'%';$('health-value').textContent=Math.ceil(state.health);$('stamina-value').textContent=Math.ceil(state.stamina);$('distance-count').textContent=Math.floor(state.distance);const region=regionAt(player.group.position.x,player.group.position.z);if(region[0]!==lastRegion){lastRegion=region[0];$('area-kicker').textContent=region[1];$('area-name').textContent=region[2];$('region-name').textContent=region[2];if(!state.visited.includes(region[0])){state.visited.push(region[0]);if(started)toast('新足迹 · '+region[2]);}}const phase=state.elapsed%90;lowTide=phase<52;const left=Math.ceil(lowTide?52-phase:90-phase);$('tide-name').textContent=lowTide?'温柔的低潮':'潮水正在上涨';$('tide-time').textContent=`${left} 秒后${lowTide?'涨潮':'退潮'} · ${lowTide?'适合探索浅滩':'厚壳更能抵御海浪'}`;if(started&&lowTide&&left<9&&!warningShown){warningShown=true;toast('海水快涨起来了，浅滩会变得难走。');}if(!lowTide)warningShown=false;}
function drawMap(){const canvas=$('minimap'),ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.save();ctx.translate(w/2,h/2+1);ctx.fillStyle='#a7cdc370';ctx.beginPath();ctx.ellipse(0,0,122,81,-.06,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e8dfb5';ctx.strokeStyle='#faf5d7';ctx.lineWidth=3;ctx.beginPath();for(let i=0;i<=70;i++){const a=i/70*Math.PI*2,e=1+.035*Math.sin(a*5)+.025*Math.cos(a*9);const x=Math.cos(a)*111*e,z=Math.sin(a)*75*e;i?ctx.lineTo(x,z):ctx.moveTo(x,z);}ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#adbd86';ctx.beginPath();ctx.ellipse(-15,-38,40,17,-.2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b0bba3';for(let i=0;i<4;i++){ctx.beginPath();ctx.ellipse(-77+i*6,-22-i*7,12,7,-.6,0,Math.PI*2);ctx.fill();}const pos=(x,z)=>[x*4.35,z*4.15];shellObjects.forEach(o=>{const[x,y]=pos(o.x,o.z);ctx.beginPath();ctx.arc(x,y,3.5,0,7);ctx.fillStyle='#fffdf0';ctx.fill();ctx.strokeStyle='#bbc5a3';ctx.lineWidth=1;ctx.stroke();});pearlObjects.forEach(o=>{if(state.pearls.includes(o.id))return;const[x,y]=pos(o.x,o.z);ctx.fillStyle='#c69b46';ctx.beginPath();ctx.moveTo(x,y-5);ctx.lineTo(x+4,y);ctx.lineTo(x,y+5);ctx.lineTo(x-4,y);ctx.fill();});const[cx,cy]=pos(campObj.x,campObj.z);ctx.fillStyle='#9c9b71';ctx.fillRect(cx-4,cy-3,8,7);ctx.beginPath();ctx.moveTo(cx-6,cy-3);ctx.lineTo(cx,cy-9);ctx.lineTo(cx+6,cy-3);ctx.fill();const[px,pz]=pos(player.group.position.x,player.group.position.z);ctx.fillStyle='#346c58';ctx.beginPath();ctx.arc(px,pz,4.5,0,7);ctx.fill();ctx.strokeStyle='#fffde6';ctx.lineWidth=2;ctx.stroke();ctx.restore();}

function start(){started=true;document.body.classList.remove('intro');$('welcome').classList.add('hidden');if(soundEnabled)sound('pickup');toast(hasSave?'欢迎回来，海岸还记得你的足迹。':'WASD 或点击沙滩移动，前面的桃色贝壳在等你。');}
$('start-button').onclick=start;if(hasSave)$('start-button').innerHTML='继续我的海岸冒险 <span>✦</span>';
$('interaction').onclick=interact;$('journal-button').onclick=showJournal;$('help-button').onclick=showHelp;$('pause-button').onclick=showPause;$('sound-button').onclick=()=>{soundEnabled=!soundEnabled;$('sound-button').classList.toggle('sound-on',soundEnabled);$('sound-button').setAttribute('aria-label',soundEnabled?'关闭声音':'打开声音');$('sound-button').title=soundEnabled?'关闭声音':'打开声音';if(soundEnabled)sound('food');save();};$('sound-button').classList.toggle('sound-on',soundEnabled);
$('modal-backdrop').addEventListener('click',e=>{if(e.target===$('modal-backdrop'))closeModal();});
document.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','Tab'].includes(e.code)&&e.code!=='Tab')e.preventDefault();if(dialogOpen&&e.code==='Tab'){const list=[...$('modal').querySelectorAll('button:not([disabled])')];if(list.length&&(e.shiftKey?document.activeElement===list[0]:document.activeElement===list.at(-1))){e.preventDefault();(e.shiftKey?list.at(-1):list[0]).focus();}return;}if(e.repeat)return;if(e.code==='Escape'){if(dialogOpen)closeModal();else showPause();return;}if(dialogOpen)return;if(e.code==='KeyE')interact();if(e.code==='KeyJ')showJournal();keys.add(e.code);if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code)){moveTarget=null;clickMarker.visible=false;}});
document.addEventListener('keyup',e=>keys.delete(e.code));
window.addEventListener('blur',()=>{keys.clear();input.x=input.z=0;dash=hide=false;save();if(started&&!dialogOpen&&!paused)showPause();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();save();if(started&&!dialogOpen&&!paused)showPause();}});
window.addEventListener('pagehide',save);
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2(),groundPlane=new THREE.Plane(new THREE.Vector3(0,1,0),-.39),hitPoint=new THREE.Vector3();
$('world').addEventListener('pointerdown',e=>{if(!started||dialogOpen||paused)return;const rect=$('world').getBoundingClientRect();pointer.set((e.clientX-rect.left)/rect.width*2-1,-((e.clientY-rect.top)/rect.height*2-1));raycaster.setFromCamera(pointer,camera);if(raycaster.ray.intersectPlane(groundPlane,hitPoint)){let x=hitPoint.x,z=hitPoint.z;const d=ellipse(x,z);if(d>1.06){x=x/d*1.06;z=z/d*1.06;}moveTarget=new THREE.Vector3(x,0,z);clickMarker.position.set(x,ground(x,z)+.08,z);clickMarker.visible=true;}});
const joy=$('joystick'),knob=$('joystick-knob');let joyPointer=null;
function joyMove(e){if(e.pointerId!==joyPointer)return;const r=joy.getBoundingClientRect();let x=e.clientX-r.left-r.width/2,z=e.clientY-r.top-r.height/2;const len=Math.hypot(x,z);if(len>34){x=x/len*34;z=z/len*34;}input.x=x/34;input.z=z/34;knob.style.transform=`translate(${x}px,${z}px)`;moveTarget=null;clickMarker.visible=false;}
joy.onpointerdown=e=>{e.preventDefault();joyPointer=e.pointerId;joy.setPointerCapture(e.pointerId);joyMove(e);};joy.onpointermove=joyMove;const endJoy=()=>{joyPointer=null;input.x=input.z=0;knob.style.transform='';};joy.onpointerup=endJoy;joy.onpointercancel=endJoy;
function touchHold(id,code){const b=$(id);b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(code);};b.onpointerup=b.onpointercancel=()=>keys.delete(code);}
touchHold('touch-dash','Space');touchHold('touch-hide','ShiftLeft');$('touch-interact').onclick=interact;
function resize(){const w=innerWidth,h=innerHeight;renderer.setSize(w,h);const view=h>w?20:18;camera.left=-view*w/h;camera.right=view*w/h;camera.top=view;camera.bottom=-view;camera.updateProjectionMatrix();}window.addEventListener('resize',resize);resize();

function update(dt){state.elapsed+=dt;invuln=Math.max(0,invuln-dt);hide=keys.has('ShiftLeft')||keys.has('ShiftRight');let ix=input.x+(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0),iz=input.z+(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0);let mx=ix*.874+iz*.486,mz=-ix*.486+iz*.874;
if(moveTarget){mx=moveTarget.x-player.group.position.x;mz=moveTarget.z-player.group.position.z;if(Math.hypot(mx,mz)<.18){moveTarget=null;clickMarker.visible=false;mx=mz=0;}}
const len=Math.hypot(mx,mz),moving=len>.06&&!hide;dash=moving&&keys.has('Space')&&state.stamina>2;const inWater=ellipse(player.group.position.x,player.group.position.z)>.87;let speed=3.25*SHELLS[state.shell].speed*(dash?1.85:1)*(inWater&&!lowTide?(.48+SHELLS[state.shell].tide*.15):1);
if(moving){mx/=len;mz/=len;player.group.position.x+=mx*speed*dt;player.group.position.z+=mz*speed*dt;const boundary=ellipse(player.group.position.x,player.group.position.z);if(boundary>1.075){player.group.position.x=player.group.position.x/boundary*1.075;player.group.position.z=player.group.position.z/boundary*1.075;if(moveTarget){moveTarget=null;clickMarker.visible=false;}}const angle=Math.atan2(mx,mz);let diff=Math.atan2(Math.sin(angle-player.group.rotation.y),Math.cos(angle-player.group.rotation.y));player.group.rotation.y+=diff*Math.min(1,dt*12);state.distance+=speed*dt;walkCycle+=dt*(dash?23:14);state.stamina=clamp(state.stamina+(dash?-24:8)*dt,0,100);}else state.stamina=Math.min(100,state.stamina+18*dt);
player.group.position.y=ground(player.group.position.x,player.group.position.z);player.body.position.y=THREE.MathUtils.lerp(player.body.position.y,hide?-.35:(moving?Math.abs(Math.sin(walkCycle))*.06:Math.sin(clockTime*2)*.025),dt*12);player.body.scale.y=THREE.MathUtils.lerp(player.body.scale.y,hide?.7:1,dt*10);player.legs.forEach((l,i)=>{l.rotation.y=moving?Math.sin(walkCycle+i*1.5)*.3:0;l.visible=!hide;});player.group.visible=invuln>0?Math.sin(clockTime*24)>-.5:true;
if(player.group.position.distanceTo(camp.position)<3){state.health=Math.min(100,state.health+8*dt);}
nearest=null;let nd=2.6;for(const o of worldObjects){const dist=Math.hypot(o.x-player.group.position.x,o.z-player.group.position.z);if(o.type==='food'&&o.available&&dist<.8){o.available=false;o.group.visible=false;o.timer=42;state.food++;state.health=Math.min(100,state.health+17);state.stamina=Math.min(100,state.stamina+20);sound('food');sparkle(o.group.position,0xffd38e,7);if(state.food===1||state.food%5===0)toast('拾到海岸果实 · 活力 +17，体力 +20');}
if(o.type==='pearl'&&!state.pearls.includes(o.id)&&dist<1.0){state.pearls.push(o.id);o.group.visible=false;sound();sparkle(o.group.position,0xffe4a2,25);toast(state.pearls.length===3?'三颗珍珠找齐了！回贝壳小屋点亮它们吧。':`找到潮汐珍珠！${state.pearls.length} / 3`);updateHUD();save();}
if(['shell','npc','camp'].includes(o.type)&&dist<nd){nearest=o;nd=dist;}}
if(nearest){$('interaction').classList.remove('hidden');$('interaction-text').textContent=nearest.type==='shell'?`看看${SHELLS[nearest.id].name}`:nearest.type==='npc'?'和阿壳聊聊天':state.pearls.length===3&&!state.won?'用珍珠点亮小屋':'在小屋歇一歇';}else $('interaction').classList.add('hidden');
for(const f of foodObjects)if(!f.available){f.timer-=dt;if(f.timer<=0){f.available=true;f.group.visible=true;}}
for(const r of rivals){r.phase+=dt*.45;r.hit=Math.max(0,r.hit-dt);const old=r.group.position.clone();r.group.position.set(r.x+Math.cos(r.phase)*1.6,.4,r.z+Math.sin(r.phase)*1.2);r.group.rotation.y=Math.atan2(r.group.position.x-old.x,r.group.position.z-old.z);r.legs.forEach((l,i)=>l.rotation.y=Math.sin(clockTime*11+i)*.2);const d=r.group.position.distanceTo(player.group.position);if(d<1.15&&r.hit<=0){if(state.shell===3){r.phase+=Math.PI;r.hit=4;sparkle(r.group.position,0xc3a6d1,8);}else if(!hide){hurt(20);r.hit=2;}}}
bird.timer-=dt;if(bird.phase==='cruise'){seagull.position.set(Math.sin(clockTime*.3)*19,8+Math.sin(clockTime*.4),Math.cos(clockTime*.3)*12);seagull.rotation.y=clockTime*.3+Math.PI/2;if(bird.timer<0&&player.group.position.distanceTo(camp.position)>4){bird.phase='warn';bird.attackTime=2.5;bird.target.copy(player.group.position);birdTarget.visible=true;birdTarget.position.copy(bird.target);birdTarget.position.y+=.045;}}
else if(bird.phase==='warn'){bird.attackTime-=dt;birdTarget.material.opacity=.35+Math.sin(clockTime*13)*.3;birdTarget.scale.setScalar(1+bird.attackTime*.22);seagull.position.lerp(new THREE.Vector3(bird.target.x,6,bird.target.z),dt*3);if(bird.attackTime<=0){bird.phase='dive';bird.attackTime=.8;}}
else {bird.attackTime-=dt;seagull.position.lerp(new THREE.Vector3(bird.target.x,.7,bird.target.z),dt*12);if(bird.attackTime<=0){if(player.group.position.distanceTo(bird.target)<1.8){if(hide){toast('躲过海鸥！有个结实的家真好。');sound('food');}else hurt(32);}bird.phase='cruise';bird.timer=between(20,30);birdTarget.visible=false;}}
$('danger').classList.toggle('hidden',bird.phase==='cruise');saveTimer+=dt;if(saveTimer>5){save();saveTimer=0;}}
const camTarget=new THREE.Vector3(0,0,3),cameraOffset=new THREE.Vector3(18,25,32),desiredTarget=new THREE.Vector3();let previous=performance.now(),hudAccum=0;
function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-previous)/1000,.05);previous=now;clockTime+=dt;const active=started&&!paused&&!dialogOpen;if(active)update(dt);waterUniforms.uTime.value=clockTime;const tideSmooth=(Math.sin((state.elapsed-50)/90*Math.PI*2)+1)*.5;water.position.y=-.18+tideSmooth*.32;foamRings.forEach((r,i)=>{r.scale.set(1+Math.sin(clockTime*.35+i)*.006,1,1+Math.sin(clockTime*.35+i)*.006);r.position.y=water.position.y+.15;});palms.forEach((p,i)=>{p.rotation.z=Math.sin(clockTime*.8+i)*.023;});shellObjects.forEach((o,i)=>{o.halo.material.opacity=.35+Math.sin(clockTime*2+i)*.2;o.model.position.y=.48+Math.sin(clockTime*1.8+i)*.06;});pearlObjects.forEach((o,i)=>{o.pearl.position.y=.72+Math.sin(clockTime*2+i)*.12;o.diamond.rotation.y=clockTime;o.diamond.position.y=1.55+Math.sin(clockTime*2+i)*.1;});wings.forEach((w,i)=>{w.rotation.z=(i?1:-1)*Math.PI/2+Math.sin(clockTime*7)*(i?1:-1)*.22;});if(!started){seagull.position.set(Math.sin(clockTime*.15)*20,9,Math.cos(clockTime*.15)*12);player.body.position.y=Math.sin(clockTime*2)*.025;}
for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.velocity.y-=dt*3;p.mesh.position.addScaledVector(p.velocity,dt);p.mesh.scale.setScalar(Math.max(0,p.life));if(p.life<=0){scene.remove(p.mesh);p.mesh.geometry.dispose();p.mesh.material.dispose();particles.splice(i,1);}}
if(started){desiredTarget.copy(player.group.position);desiredTarget.x=clamp(desiredTarget.x,-11,12);desiredTarget.z=clamp(desiredTarget.z,-6,8);desiredTarget.y=0;}else desiredTarget.set(0,0,1);camTarget.lerp(desiredTarget,1-Math.exp(-dt*2.2));camera.position.copy(camTarget).add(cameraOffset);camera.lookAt(camTarget);playerShadow.position.set(player.group.position.x,ground(player.group.position.x,player.group.position.z)+.035,player.group.position.z);playerShadow.scale.setScalar(hide?.7:1);hudAccum+=dt;if(hudAccum>.12){tickHUD();drawMap();hudAccum=0;}renderer.render(scene,camera);}
updateHUD();tickHUD();drawMap();document.body.classList.add('intro');$('loading').classList.add('hidden');requestAnimationFrame(frame);

// A read-only game state tool helps supported agents explain the current adventure.
const getStatus=()=>({started,paused:paused||dialogOpen,shell:SHELLS[state.shell].name,health:Math.round(state.health),stamina:Math.round(state.stamina),pearls:state.pearls.length,discovered:state.discovered.map(i=>SHELLS[i].name),quest:state.won?'冒险已完成':questTitles[questStage()],region:regionAt(player.group.position.x,player.group.position.z)[2],tide:lowTide?'低潮':'涨潮',won:state.won});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_shellbound_adventure',title:'查看寄居日记冒险进度',description:'Read the current shell, health, tide, quest and pearl collection without changing the game.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(input&&Object.keys(input).length)throw new Error('此工具不接受参数');return getStatus();}})).catch(()=>{});}catch{}}
// Intentional inspection surface for local gameplay QA; it does not change progression.
window.shellbound={getStatus,renderInfo:()=>({calls:renderer.info.render.calls,triangles:renderer.info.render.triangles}),getPosition:()=>({x:player.group.position.x,z:player.group.position.z}),getShellLocations:()=>shellObjects.map(o=>({id:o.id,x:o.x,z:o.z})),getPearlLocations:()=>pearlLocations};
